#!/usr/bin/env python3
"""Build 003R artifacts from structured briefs and verified outputs; never reads expected/golden files."""
from pathlib import Path
import hashlib, json, re, subprocess, sys
ROOT=Path(__file__).resolve().parents[1]
REPORTS=ROOT/'reports'; DOCS=ROOT/'docs'; CASES=ROOT/'selection_cases'; RUNS=ROOT/'selector_runs'

def load(path): return json.loads(Path(path).read_text(encoding='utf-8'))
def write(path,text): path.parent.mkdir(parents=True,exist_ok=True); path.write_text(text.rstrip()+'\n',encoding='utf-8')
def sha(path): return hashlib.sha256(Path(path).read_bytes()).hexdigest()

# Run the selector using only structured brief inputs, rule catalog, and versioned dataset.
selector=ROOT/'scripts/select.py'; data=ROOT/'dataset/v1'; rules=ROOT/'rules/selection-rules.json'
case_paths=sorted(CASES.glob('*/brief.json'))
if len(case_paths)<12: raise SystemExit(f'Expected 3 base plus at least 9 counterfactual briefs, found {len(case_paths)}')
case_rows=[]
for brief_path in case_paths:
    name=brief_path.parent.name; out=RUNS/name; out.mkdir(parents=True,exist_ok=True)
    subprocess.run([sys.executable,str(selector),'--brief',str(brief_path),'--dataset',str(data),'--rules',str(rules),'--out',str(out)],check=True,capture_output=True,text=True)
    s=load(out/'selection.json'); r=load(out/'rejections.json'); t=load(out/'decision_trace.json')
    case_rows.append({'name':name,'brief':brief_path.relative_to(ROOT).as_posix(),'status':s['overall_decision']['status'],'selected_count':len(s['selected_records']),'rejected_count':len(r['rejected_records']),'feature_decision_count':len(r['feature_decisions']),'gate_results':s['gate_results'],'selected_ids':[x['record_id'] for x in s['selected_records']],'selected_rules':{x['record_id']:x['rule_id'] for x in s['selected_records']},'source_exclusions':t.get('source_exclusions',[])})

rule_data=load(rules)
rule_lines=['# 003R deterministic selection rules','',f"Rules version **{rule_data['rules_version']}**. Precedence is safety-first and follows priority descending. Unknown remains distinct from false; explicit exclusions suppress inferred defaults.",'','| Priority | Stable rule ID | Name | Predicate | Effect |','|---:|---|---|---|---|']
by_id={x['rule_id']:x for x in rule_data['rules']}
for rid in rule_data['precedence_high_to_low']:
    x=by_id[rid]
    rule_lines.append(f"| {x['priority']} | `{rid}` | {x['name']} | {x['predicate'].replace('|','\\|')} | {x['effect'].replace('|','\\|')} |")
rule_lines += ['', '## Scoped source exclusions','']
for sid,override in sorted(rule_data.get('source_scope_overrides',{}).items()):
    rule_lines.append(f"- `{sid}` may support only `{', '.join(override['allowed_software_type_ids'])}`. For other types, the selector records `{override['reason_code']}` under `{override['rule_id']}`: {override['rationale']}")
rule_lines += ['', '## Deterministic tie handling','', 'The selector uses fixed rule order, sorted record IDs, stable relationship IDs, and lexicographically ordered ready roadmap tasks. It does not call an LLM, access the network, read expected/golden outputs, or write into the dataset.']
write(DOCS/'rule-table.md','\n'.join(rule_lines))

# Human-readable outcome and source/decision-path digest.
path_lines=['# 003R selector decision paths','', 'Each case was generated by `scripts/select.py` from its `selection_cases/<case>/brief.json`, the versioned JSONL graph and the stable rule catalog. Full candidate outputs and per-record evidence chains are in `selector_runs/`; every selected record has a typed category edge, a `supported_by` source edge, and an exact claim locator. `decision_trace.json` traverses active `requires`, `verified_by`, and `produces` edges; `informs` is retained as typed related context, not a prerequisite. The baseline contains no active `produces` edges; this absence is reported rather than synthesized. Roadmap task DAG edges, scope exclusions, and input/rules/dataset hashes are also recorded.', '', '| Case | Overall status | Selected | Rejected | Gates |', '|---|---|---:|---:|---|']
for row in case_rows:
    gates=', '.join(f'{key}: {value}' for key,value in row['gate_results'].items()) or 'none'
    path_lines.append(f"| `{row['name']}` | `{row['status']}` | {row['selected_count']} | {row['rejected_count']} | {gates} |")
path_lines += ['', '## Selected-record source routes in the three base cases','']
for name in ('base_ai_agent','base_authenticated_api','base_offline_cli'):
    out=RUNS/name;s=load(out/'selection.json');t=load(out/'decision_trace.json')
    path_lines += [f'### `{name}`','']
    for record in s['selected_records']:
        paths=[]
        for route in record['evidence_paths']:
            for source in route['sources']:
                paths.append(f"`{route['software_type_id']}` → `{record['record_id']}` → `{source['source_id']}` ({source['claim_locator']})")
        path_lines.append(f"- `{record['record_id']}` — `{record['status']}` by `{record['rule_id']}`; routes: {'; '.join(paths)}")
    if t.get('source_exclusions'):
        path_lines += ['', 'Source-scope exclusions:']
        for x in t['source_exclusions']:
            path_lines.append(f"- `{x['software_type_id']}` excludes `{x['source_id']}` from `{x['record_id']}` at `{x['claim_locator']}` under `{x['rule_id']}` ({x['reason_code']}).")
    path_lines.append('')
write(REPORTS/'decision-paths-003r.md','\n'.join(path_lines))

# Mutation outcomes are derived from the regression runner's test transcript.
reg_path=REPORTS/'regression-tests.json'
reg=load(reg_path) if reg_path.exists() else {'status':'NOT_RUN','tests_run':0,'output':''}
transcript=reg.get('output','')
mutation_tests={
    'recommended_status_flip':('test_mutation_flip_recommended_status_is_detected','A fixed independent oracle must reject a changed RECOMMENDED status.'),
    'critical_rejection_reason_reversal':('test_mutation_reverse_rejection_reason_is_detected','Typed rejection rationale must match the fixed independent oracle.'),
    'fabricated_test_or_deployment_PASS':('test_mutation_fake_pass_is_rejected_by_output_schema','PASS is rejected by the output contract; source files or workflow configuration are not execution evidence.'),
    'descriptive_text_conflict':('test_mutation_free_text_cannot_override_structured_facts','Adversarial descriptive prose is ignored and omitted; structured decisions remain unchanged.'),
}
mutations=[]
for name,(test_id,description) in mutation_tests.items():
    passed=bool(re.search(re.escape(test_id)+r'.*\.\.\. ok',transcript))
    mutations.append({'control':name,'test_id':test_id,'description':description,'status':'PASS' if passed else 'FAIL'})
mutation_report={'status':'PASS' if all(x['status']=='PASS' for x in mutations) else 'FAIL','mutations':mutations,'expected_control_behavior':'The first three unsafe mutations are caught; the descriptive-text mutation has no decision effect and is explicitly ignored.'}
write(REPORTS/'selector-mutation-results.json',json.dumps(mutation_report,indent=2,ensure_ascii=False))

verification=load(REPORTS/'selector-verification.json') if (REPORTS/'selector-verification.json').exists() else {'oracle_pass':0,'oracle_fail':-1,'cleanroom_no_oracle_access':'NOT_RUN','negative_controls':{'status':'NOT_RUN','count':0}}
version=load(REPORTS/'version-map.json') if (REPORTS/'version-map.json').exists() else {}
dataset_report=load(REPORTS/'dataset-validation.json') if (REPORTS/'dataset-validation.json').exists() else {'status':'NOT_RUN','error_count':-1}
fixture_report=load(REPORTS/'fixture-validation.json') if (REPORTS/'fixture-validation.json').exists() else {'status':'NOT_RUN','error_count':-1}
regression=load(reg_path) if reg_path.exists() else {'status':'NOT_RUN','tests_run':0,'failures':[],'errors':[]}
parent_dataset=load(ROOT/'research/parent-003-dataset-hashes.json') if (ROOT/'research/parent-003-dataset-hashes.json').exists() else {'all_dataset_members_unchanged':False}
all_pass=(verification.get('oracle_fail',1)==0 and verification.get('cleanroom_no_oracle_access')=='PASS' and verification.get('negative_controls',{}).get('status')=='PASS' and dataset_report.get('status')=='PASS' and fixture_report.get('status')=='PASS' and regression.get('status')=='PASS' and mutation_report['status']=='PASS' and version.get('preservation',{}).get('all_001_ids_preserved') and version.get('preservation',{}).get('all_002_ids_preserved') and parent_dataset.get('all_dataset_members_unchanged'))
summary={'project':'STUDIO-KNOWLEDGE-003R','scope':'research-only deterministic selector calibration; no Stage 004 or Studio integration','status':'PASS' if all_pass else 'FAIL','dataset_integrity':{'status':dataset_report.get('status'),'errors':dataset_report.get('error_count'),'all_001_ids_preserved':version.get('preservation',{}).get('all_001_ids_preserved'),'all_002_ids_preserved':version.get('preservation',{}).get('all_002_ids_preserved'),'003_parent_dataset_unchanged':parent_dataset.get('all_dataset_members_unchanged'),'003_parent_dataset_member_count':parent_dataset.get('dataset_member_count')},'fixture_integrity':{'status':fixture_report.get('status'),'fixture_count':fixture_report.get('fixture_count')},'selection_reliability':{'cases':len(case_rows),'frozen_oracle_pass':verification.get('oracle_pass'),'frozen_oracle_fail':verification.get('oracle_fail'),'cleanroom_no_oracle_access':verification.get('cleanroom_no_oracle_access')},'safety_abstention':{'negative_controls':verification.get('negative_controls',{}).get('count'),'status':verification.get('negative_controls',{}).get('status'),'mutation_controls':len(mutations),'mutation_status':mutation_report['status'],'gate_PASS_emitted':False},'studio_integration_readiness':'NO-GO / NOT STARTED','stage_004_authorized':False,'limitations':['Only three calibrated archetypes are represented, with one base case each and nine+ structured counterfactual cases.','No product runtime, tests, CI, deployment, release, or compliance outcome is claimed.','Passing these research checks is not authorization for production or Studio integration.']}
write(REPORTS/'validation-report-003r.json',json.dumps(summary,indent=2,ensure_ascii=False))

decision=['# STUDIO-KNOWLEDGE-003R decision','', '## Separate gate decisions','', '| Area | Decision | Evidence |','|---|---|---|',
 f"| Dataset integrity | **{'GO' if summary['dataset_integrity']['status']=='PASS' and summary['dataset_integrity']['all_001_ids_preserved'] and summary['dataset_integrity']['all_002_ids_preserved'] else 'NO-GO'}** | Draft 2020-12 schemas, graph/source/roadmap checks, inherited fixture validation, and 001/002 stable-ID preservation: {summary['dataset_integrity']['status']}; 003 baseline JSONL remains unchanged. |",
 f"| Novel brief selection reliability | **{'GO — narrow archetypes' if summary['selection_reliability']['frozen_oracle_fail']==0 and summary['selection_reliability']['cases']>=12 else 'NO-GO'}** | {summary['selection_reliability']['frozen_oracle_pass']}/{summary['selection_reliability']['cases']} base/counterfactual cases match the separately frozen oracle exactly; clean-room run has no oracle files. |",
 f"| Safety abstention | **{'GO — tested boundaries' if summary['safety_abstention']['status']=='PASS' and summary['safety_abstention']['mutation_status']=='PASS' else 'NO-GO'}** | Five inherited negative controls and four targeted mutation controls pass; source-scope mismatch is explicitly excluded; no gate PASS is emitted. |",
 '| Studio integration readiness | **NO-GO / NOT STARTED** | No product generator, hosted service, Studio integration, search/vector DB, frontend, payment, deployment, or commercial code was built. |','',
 f"## Overall disposition: **{'PARTIAL' if all_pass else 'NO-GO'}**",'', 'The selector is a small research prototype for the three calibrated archetypes, not a general-purpose generator. It consumes structured facts, preserves unknown/false distinctions, and emits typed selections, exclusions, prompt requirements, incomplete gates, and dependency-aware roadmaps. The latest tested suite contains three base briefs and ten counterfactuals. Tests, CI, releases, approvals, and compliance are not inferred from source files or authored plans.', '', '## Stop conditions','', '- Do not start Stage 004; this directive explicitly prohibits it.', '- Do not treat this narrow prototype as production-ready or integrate it into Studio without a separate authorization, broader calibration, security review, and operational evidence.', '- Seven catalog types remain `NOT_CALIBRATED`; three represented types still have only one base archetype each.', '']
write(REPORTS/'decision-003r.md','\n'.join(decision))

change=['# STUDIO-KNOWLEDGE-003R change log','', 'This is an additive research-only continuation from the frozen STUDIO-KNOWLEDGE_003 checkpoint. The 003 ZIP and 001/002 archives were not edited or embedded.', '', '## Changes', '', '- Added a small deterministic CLI selector that reads only structured briefs, the stable rule catalog, and the versioned 003 JSONL dataset; it does not load expected/golden files.', '- Added strict input and three output schemas, stable prioritized rules, contradiction/missing-input handling, explicit unknown/false semantics, unsupported-category abstention, and a no-PASS gate contract.', '- Added explicit source-scope override for `source.mobile_applications.01`; an API branch cannot cite mobile-only guidance. The exclusion is emitted with exact claim locator and rationale in the decision trace.', '- Added catalog-derived prompt requirements, candidate-bound evidence guards, authority checks, and typed graph traversal for `requires`, `verified_by`, and `produces`; typed `informs` edges remain separately traced context and cannot become prerequisites. The inherited baseline has no active `produces` edges.', '- Independently froze the oracle before selector implementation; base expectations derive from the immutable 003 fixtures and counterfactuals from structured facts and directive criteria.', '- Added ten counterfactual briefs (three per required archetype plus a standards-edition case), four mutation tests, five inherited negative controls, clean-room isolation checks, and exact oracle comparison.', '- Added final selector runs, path traces, human-readable rule table, source/decision path report, mutation report, 003R validation report, and detached archive hash at packaging.', '', '## Reproducibility and limitations', '', '- Re-running the selector overwrites only its designated output directory; JSONL dataset partitions are read-only.', '- Fixture/oracle status is evidence about these defined cases only. Seven catalog categories remain uncalibrated; no Studio integration or Stage 004 work was performed.', '- No product test, CI workflow, deployment, release, action approval, or compliance result is claimed. All applicable execution gates remain incomplete.']
write(REPORTS/'change-log-003r.md','\n'.join(change))

readme=['# STUDIO-KNOWLEDGE-003R — deterministic selection research checkpoint','', 'This research-only corrective increment tests whether a small deterministic policy can select a scoped SDLC, prompt contract, and dependency-aware roadmap for three calibrated project archetypes. It starts from the frozen 003 dataset and does not modify the original 003 checkpoint, 001/002 archives, Studio, hosted systems, or commercial product code.', '', '## Contents','', '- `dataset/v1/` — inherited 003 versioned JSONL dataset, unchanged in this increment.','- `selection_cases/` — three structured base briefs plus ten counterfactual briefs.','- `oracles/frozen-oracle.json` — independently authored exact expectations; selector never reads it.','- `rules/selection-rules.json` — prioritized deterministic rule catalog and reviewed source-scope override.','- `scripts/select.py` — read-only selector CLI.','- `schemas/selector-input.schema.json` and `schemas/*output.schema.json` — Draft 2020-12 contracts.','- `selector_runs/` — candidate selections, rejections, and decision traces for every brief.','- `tests/test_selector.py` — exact expectations, source/graph checks, negative controls, and adversarial mutations.','- `reports/decision-003r.md` — separate integrity, selection, safety, and integration decisions.','', '## Reproduce','', 'Requires Python 3.10+ and `jsonschema` with Draft 2020-12 support. From the project directory:','', '```bash','python3 scripts/select.py --brief selection_cases/base_ai_agent/brief.json --dataset dataset/v1 --rules rules/selection-rules.json --out /tmp/selector-output','python3 scripts/verify_selector.py','python3 scripts/run_regression_tests.py','python3 scripts/verify_manifest.py --root .','```','', 'The selector reads a brief, the versioned graph and the rule catalog only. The separate verifier may read the frozen oracle. Selector output files are not read back by the selector.', '', '## Decision boundary','', 'GO applies only to dataset integrity, exact replay of these 13 cases, and safety-abstention tests. Overall disposition is PARTIAL. This is not a general product generator or Studio integration; Stage 004 remains prohibited by the directive. No test/CI/deployment/release/compliance PASS is claimed.']
write(ROOT/'README.md','\n'.join(readme))
print(json.dumps({'runs':len(case_rows),'reports':['decision-003r.md','validation-report-003r.json','decision-paths-003r.md','selector-mutation-results.json'],'status':summary['status']},indent=2))
